type ProjectStatusRow = { name: string; color: string; subStages?: Array<{ name: string; color: string; isDefault?: boolean }> };
const statusDefaults = ["New", "Quoting", "Drafting", "Ready for CNC", "Running", "In Production", "Paused", "Completed"];
function fallbackStatusPillColors(status: string) {
  const key = String(status || "").trim().toLowerCase();
  const defaults: Record<string, string> = {
    new: "#3060D0",
    running: "#2A7A3B",
    "in production": "#2A7A3B",
    drafting: "#6B4FB3",
    quoting: "#C77700",
    "ready for cnc": "#3060D0",
    completed: "#2A7A3B",
    paused: "#A05A00",
    complete: "#2A7A3B",
    "on hold": "#C77700",
  };
  const bg = defaults[key] ?? "#64748B";
  return { backgroundColor: bg, color: isLightHex(bg, 0.75) ? "#0F172A" : "#FFFFFF" };
}

// Contact-card theming for the General tab's Client Details card —
// the same recipe as the Contacts page's contact view (clients/page.tsx): one registered <color>
// custom property (--ambient-color, see globals.css) that every tint is color-mixed from, so a change
// cross-fades everywhere at once.
const CONTACT_NEUTRAL_COLOR = "#7D99B3";
const DEFAULT_CONTACT_CATEGORIES: Array<{ name: string; color: string }> = [
  { name: "Clients", color: "#4ADE80" },
  { name: "Contractor", color: "#F2A33C" },
  { name: "Supplier", color: "#7D99B3" },
];
function ambientMix(percent: number) {
  return `color-mix(in srgb, var(--ambient-color) ${percent}%, transparent)`;
}
// Dark initials on a light category colour, white on a dark one (same threshold as the Contacts page).
function contactBadgeTextOn(color: string) {
  return isLightHex(color, 0.62) ? "#0F172A" : "#FFFFFF";
}

function normalizeProjectStatuses(raw: unknown): ProjectStatusRow[] {
  if (!Array.isArray(raw)) {
    return [
      { name: "New", color: "#3060D0" },
      { name: "In Production", color: "#2A7A3B" },
      { name: "On Hold", color: "#C77700" },
      { name: "Complete", color: "#2A7A3B" },
    ];
  }
  const rows = raw
    .filter((item) => item && typeof item === "object")
    .map((item) => {
      const row = item as Record<string, unknown>;
      // Its sub-statuses (Company Settings › Project statuses) — for the status pill and its menu.
      const subStages = (Array.isArray(row.subStages) ? row.subStages : [])
        .filter((sub) => sub && typeof sub === "object")
        .map((sub) => {
          const subRow = sub as Record<string, unknown>;
          return {
            name: String(subRow.name ?? "").trim(),
            color: String(subRow.color ?? "").trim() || "#64748B",
            isDefault: Boolean(subRow.isDefault),
          };
        })
        .filter((sub) => sub.name);
      return {
        name: String(row.name ?? "").trim(),
        color: String(row.color ?? "").trim() || "#64748B",
        subStages,
      };
    })
    .filter((row) => row.name);
  return rows.length
    ? rows
    : [
        { name: "New", color: "#3060D0" },
        { name: "In Production", color: "#2A7A3B" },
        { name: "On Hold", color: "#C77700" },
        { name: "Complete", color: "#2A7A3B" },
      ];
}

// Dates below follow the company's date format (Company Settings > Regional formats) via
// lib/company-formats.ts; times are always the viewer's own local time.
function shortDate(value: string) {
  return activeDateTime(value, " ") || "-";
}

function dashboardStyleDate(value: string) {
  return activeDateTime(value) || "-";
}

// Same as dashboardStyleDate — kept as its own name for the Specifications "Version History" cards.
function shortMonthStyleDate(value: string) {
  return activeDateTime(value) || "-";
}

// The date (company format) plus a separate 12-hour time string — used by the Quote "Pending"/
// "Accepted" banners above the sheet.
function numericDDMMYYYYAndTime(value: string): { date: string; time: string } {
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return { date: "-", time: "-" };
  const time = new Intl.DateTimeFormat(undefined, { hour: "numeric", minute: "2-digit", hour12: true })
    .format(d)
    .toLowerCase()
    .replace(/\s+/g, "");
  return { date: activeDate(d), time };
}

// "1st"/"2nd"/"3rd"/"4th"..."11th"/"12th"/"13th" (the 11-13 teens are always "th", not "st"/"nd"/
// "rd", despite ending in 1/2/3) — standard English ordinal rule.
function ordinalSuffix(day: number): string {
  if (day % 100 >= 11 && day % 100 <= 13) return "th";
  switch (day % 10) {
    case 1:
      return "st";
    case 2:
      return "nd";
    case 3:
      return "rd";
    default:
      return "th";
  }
}

function dashboardStyleDateOnly(value: string) {
  return activeDate(value) || "-";
}

function initials(text: string) {
  const cleaned = String(text || "").trim();
  if (!cleaned) return "?";
  const parts = cleaned.split(/\s+/).filter(Boolean);
  if (parts.length === 1) {
    return parts[0].slice(0, 2).toUpperCase();
  }
  return `${parts[0][0] ?? ""}${parts[1][0] ?? ""}`.toUpperCase();
}


function quoteColumnWidthPercent(span: number): number {
  const safeSpan = Math.max(1, Math.min(12, Number(span) || 12));
  return (safeSpan / 12) * 100;
}

function quotePaperDimensionsFor(pageSize: string): { widthMm: number; heightMm: number } {
  const key = String(pageSize || "").trim().toUpperCase();
  switch (key) {
    case "A3":
      return { widthMm: 297, heightMm: 420 };
    case "A5":
      return { widthMm: 148, heightMm: 210 };
    case "LETTER":
      return { widthMm: 216, heightMm: 279 };
    case "LEGAL":
      return { widthMm: 216, heightMm: 356 };
    case "A4":
    default:
      return { widthMm: 210, heightMm: 297 };
  }
}

function quoteBlockCountsAsContent(block: QuoteTemplateBlock): boolean {
  return block.type !== "divider" && block.type !== "spacer";
}

function normalizePersonLookup(value: unknown): string {
  return String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}

function normalizeSalesQuoteHelpers(raw: unknown): SalesQuoteHelperRow[] {
  if (!Array.isArray(raw)) return [];
  return raw
    .filter((item) => item && typeof item === "object")
    .map((item, idx) => {
      const row = item as Record<string, unknown>;
      const content = sanitizeQuoteRichTextMarkup(String(row.content ?? ""));
      return {
        id: String(row.id ?? `quote_helper_${idx + 1}`).trim(),
        content,
      };
    })
    .filter((row) => row.content.trim());
}

function normalizeSalesQuoteSnapshotRow(item: Record<string, unknown>, fallbackVersion: number): SalesQuoteSnapshotRow {
  const pageImagePaths = Array.isArray(item.pageImagePaths)
    ? item.pageImagePaths.map((value) => String(value ?? "").trim()).filter(Boolean)
    : [];
  const pageImageUrls = Array.isArray(item.pageImageUrls)
    ? item.pageImageUrls.map((value) => String(value ?? "").trim()).filter(Boolean)
    : [];
  const pageHtml = Array.isArray(item.pageHtml)
    ? item.pageHtml.map((value) => String(value ?? "")).filter(Boolean)
    : [];
  return {
    id: String(item.id ?? `snapshot_${fallbackVersion}`).trim() || `snapshot_${fallbackVersion}`,
    version: Math.max(1, Number(item.version ?? fallbackVersion) || fallbackVersion),
    createdAt: String(item.createdAt ?? ""),
    createdByUid: String(item.createdByUid ?? "").trim(),
    createdByName: String(item.createdByName ?? "").trim(),
    capturedProjectMarker: String(item.capturedProjectMarker ?? "").trim(),
    signature: String(item.signature ?? ""),
    totalFormatted: String(item.totalFormatted ?? ""),
    pageCount: Math.max(1, Number(item.pageCount ?? pageHtml.length ?? pageImageUrls.length ?? 1) || 1),
    pageWidthMm: Math.max(10, Number(item.pageWidthMm ?? 210) || 210),
    pageHeightMm: Math.max(10, Number(item.pageHeightMm ?? 297) || 297),
    pageHtml,
    pageHtmlPath: String(item.pageHtmlPath ?? "").trim(),
    pageHtmlUrl: String(item.pageHtmlUrl ?? "").trim(),
    pdfPath: String(item.pdfPath ?? "").trim(),
    pdfUrl: String(item.pdfUrl ?? "").trim(),
    pdfFileName: String(item.pdfFileName ?? "").trim(),
    pageImagePaths,
    pageImageUrls,
  } satisfies SalesQuoteSnapshotRow;
}

function extractClientRegion(address: unknown, explicitRegion?: unknown): string {
  const directRegion = String(explicitRegion ?? "").trim();
  if (directRegion) return directRegion;

  const rawAddress = String(address ?? "").replace(/\r/g, "").trim();
  if (!rawAddress) return "";

  const commaParts = rawAddress
    .split(",")
    .map((part) => part.trim())
    .filter(Boolean);
  if (commaParts.length >= 2) {
    return commaParts[1] || "";
  }

  const lineParts = rawAddress
    .split("\n")
    .map((part) => part.trim())
    .filter(Boolean);
  if (lineParts.length >= 2) {
    return lineParts[1] || "";
  }

  return "";
}

function escapeQuoteRichTextHtml(value: string): string {
  return String(value || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function sanitizeAllowedQuoteInlineStyle(styleText: string): string {
  const allowed: string[] = [];
  for (const rawPart of String(styleText || "").split(";")) {
    const [rawName, ...rawValueParts] = rawPart.split(":");
    const name = String(rawName || "").trim().toLowerCase();
    const value = rawValueParts.join(":").trim();
    if (!name || !value) continue;
    if (
      name === "color" &&
      (/^#[0-9a-fA-F]{3,8}$/.test(value) ||
        /^[a-zA-Z]+$/.test(value) ||
        /^rgba?\([\d\s.,%]+\)$/i.test(value))
    ) {
      allowed.push(`color:${value}`);
      continue;
    }
    if (name === "font-family" && /^[a-zA-Z0-9\s,'"()-]+$/.test(value)) {
      allowed.push(`font-family:${value}`);
      continue;
    }
    if (name === "font-size" && /^\d+(px|pt|em|rem|%)$/.test(value)) {
      allowed.push(`font-size:${value}`);
      continue;
    }
    if (name === "text-align" && /^(left|center|right|justify)$/i.test(value)) {
      allowed.push(`text-align:${value.toLowerCase()}`);
    }
  }
  return allowed.join("; ");
}

function sanitizeQuoteRichTextMarkup(value: string): string {
  if (typeof document === "undefined") {
    return escapeQuoteRichTextHtml(value)
      .replace(/\r\n/g, "\n")
      .split(/\n{2,}/)
      .map((paragraph) => `<p>${paragraph.replace(/\n/g, "<br />")}</p>`)
      .join("");
  }

  const template = document.createElement("template");
  template.innerHTML = String(value || "");

  const renderNode = (node: Node): string => {
    if (node.nodeType === Node.TEXT_NODE) {
      return escapeQuoteRichTextHtml(String(node.textContent || "").replace(/\u200b/g, "")).replace(/\r?\n/g, "<br />");
    }
    if (node.nodeType !== Node.ELEMENT_NODE) return "";

    const element = node as HTMLElement;
    const tag = element.tagName.toLowerCase();
    const children = Array.from(element.childNodes).map(renderNode).join("");

    if (tag === "br") return "<br />";
    if (tag === "div" || tag === "p") {
      const safeStyle = sanitizeAllowedQuoteInlineStyle(element.getAttribute("style") || "");
      return safeStyle
        ? `<p style="${safeStyle}">${children || "<br />"}</p>`
        : `<p>${children || "<br />"}</p>`;
    }
    if (tag === "strong" || tag === "b") return `<strong>${children}</strong>`;
    if (tag === "em" || tag === "i") return `<em>${children}</em>`;
    if (tag === "u") return `<u>${children}</u>`;
    if (tag === "s" || tag === "strike" || tag === "del") return `<s>${children}</s>`;
    if (tag === "span" || tag === "font") {
      const rawStyle =
        tag === "font"
          ? [
              element.getAttribute("color") ? `color:${element.getAttribute("color")}` : "",
              element.getAttribute("face") ? `font-family:${element.getAttribute("face")}` : "",
            ]
              .filter(Boolean)
              .join("; ")
          : (element.getAttribute("style") || "");
      const safeStyle = sanitizeAllowedQuoteInlineStyle(rawStyle);
      return safeStyle ? `<span style="${safeStyle}">${children}</span>` : children;
    }
    return children;
  };

  return Array.from(template.content.childNodes)
    .map(renderNode)
    .join("")
    .replace(/(?:<p><br \/><\/p>){3,}/gi, "<p><br /></p><p><br /></p>");
}

function renderQuoteRichTextHtml(value: string): string {
  return sanitizeQuoteRichTextMarkup(value);
}

function quoteRichTextHasVisibleContent(value: string): boolean {
  return stripHtmlToPlainText(value).length > 0;
}

function normalizeQuoteBoxStyle(raw: unknown): QuoteTemplateBoxStyle {
  if (!raw || typeof raw !== "object") return {};
  const item = raw as Record<string, unknown>;
  return {
    borderColor: toStr(item.borderColor),
    borderWidthPx: toStr(item.borderWidthPx),
    fillColor: toStr(item.fillColor),
    paddingPx: toStr(item.paddingPx),
    paddingTopPx: toStr(item.paddingTopPx),
    paddingBottomPx: toStr(item.paddingBottomPx),
    paddingLeftPx: toStr(item.paddingLeftPx),
    paddingRightPx: toStr(item.paddingRightPx),
    marginPx: toStr(item.marginPx),
  };
}

function quoteSafePixelString(value: string | undefined): string | undefined {
  const num = Number.parseInt(String(value ?? "").replace(/[^\d-]/g, ""), 10);
  if (!Number.isFinite(num)) return undefined;
  return `${num}px`;
}

