function dedupeProjectLiveTabs(
  tabs: ProjectLiveTabRecord[],
  preferredActiveId?: string,
): ProjectLiveTabRecord[] {
  const preferredId = String(preferredActiveId || "").trim();
  const byViewKey = new Map<string, ProjectLiveTabRecord>();
  for (const tab of tabs) {
    if (!tab || !tab.viewKey || !tab.id) continue;
    const existing = byViewKey.get(tab.viewKey);
    if (!existing) {
      byViewKey.set(tab.viewKey, tab);
      continue;
    }
    if (preferredId && tab.id === preferredId) {
      byViewKey.set(tab.viewKey, tab);
    }
  }
  return Array.from(byViewKey.values());
}
