    <span
      aria-hidden="true"
      className="inline-block"
      style={{
        width: 9,
        height: 9,
        backgroundColor: color || "#0F172A",
        WebkitMaskImage: "url('/Arrow.png')",
        WebkitMaskRepeat: "no-repeat",
        WebkitMaskPosition: "center",
        WebkitMaskSize: "contain",
        maskImage: "url('/Arrow.png')",
        maskRepeat: "no-repeat",
        maskPosition: "center",
        maskSize: "contain",
      }}
    />
