  // "Closing" mirrors the image viewer's own Comments panel (projectImageViewerCommentsClosing):
  // on close, the panel stays MOUNTED for one more animation frame so its slide-out (below) can
  // actually play, then *Open flips false once that's finished. Only meaningful while *Open is still
  // true — toggleQuoteExtrasPanel/toggleQuoteHistoryPanel own the full open/close sequencing below.
  const [isQuoteExtrasPanelClosing, setIsQuoteExtrasPanelClosing] = useState(false);
  const [isQuoteHistoryPanelClosing, setIsQuoteHistoryPanelClosing] = useState(false);
  // True only for a brief window right after the panel opens — while true, its items get the
  // slide-in entrance animation; once it flips back to false, items render in their resting state
  // with NO animation property at all, so a later content change (switching versions, toggling an
  // extra — anything that re-renders or even remounts a row, e.g. because a historical version's
  // groups carry different ids than the live grid's) never replays the pop-in. Without this, EVERY
  // row always carried an animation style, so any row that got freshly mounted for an unrelated
  // reason played its entrance again — first opening the panel is the only time that's wanted.
  const [isQuoteExtrasPanelJustOpened, setIsQuoteExtrasPanelJustOpened] = useState(false);
  const [isQuoteHistoryPanelJustOpened, setIsQuoteHistoryPanelJustOpened] = useState(false);
  const quoteExtrasPanelCloseTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const quoteHistoryPanelCloseTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const quoteExtrasPanelOpenTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const quoteHistoryPanelOpenTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const toggleQuoteExtrasPanel = useCallback(() => {
    if (quoteExtrasPanelCloseTimeoutRef.current) {
      clearTimeout(quoteExtrasPanelCloseTimeoutRef.current);
      quoteExtrasPanelCloseTimeoutRef.current = null;
    }
    setIsQuoteExtrasPanelOpen((wasOpen) => {
      if (!wasOpen) {
        setIsQuoteExtrasPanelClosing(false);
        setIsQuoteExtrasPanelJustOpened(true);
        if (quoteExtrasPanelOpenTimeoutRef.current) clearTimeout(quoteExtrasPanelOpenTimeoutRef.current);
        // 480ms entrance + up to 280ms of stagger delay — 800ms comfortably covers even the
        // last-staggered item finishing before animations are turned off again.
        quoteExtrasPanelOpenTimeoutRef.current = setTimeout(() => {
          setIsQuoteExtrasPanelJustOpened(false);
          quoteExtrasPanelOpenTimeoutRef.current = null;
        }, 800);
        return true;
      }
      setIsQuoteExtrasPanelClosing(true);
      quoteExtrasPanelCloseTimeoutRef.current = setTimeout(() => {
        setIsQuoteExtrasPanelOpen(false);
        setIsQuoteExtrasPanelClosing(false);
        quoteExtrasPanelCloseTimeoutRef.current = null;
      }, 360);
      return true;
    });
  }, []);
  const toggleQuoteHistoryPanel = useCallback(() => {
    if (quoteHistoryPanelCloseTimeoutRef.current) {
      clearTimeout(quoteHistoryPanelCloseTimeoutRef.current);
      quoteHistoryPanelCloseTimeoutRef.current = null;
    }
    setIsQuoteHistoryPanelOpen((wasOpen) => {
      if (!wasOpen) {
        setIsQuoteHistoryPanelClosing(false);
        setIsQuoteHistoryPanelJustOpened(true);
        if (quoteHistoryPanelOpenTimeoutRef.current) clearTimeout(quoteHistoryPanelOpenTimeoutRef.current);
        quoteHistoryPanelOpenTimeoutRef.current = setTimeout(() => {
          setIsQuoteHistoryPanelJustOpened(false);
          quoteHistoryPanelOpenTimeoutRef.current = null;
        }, 800);
        return true;
      }
      setIsQuoteHistoryPanelClosing(true);
      quoteHistoryPanelCloseTimeoutRef.current = setTimeout(() => {
        setIsQuoteHistoryPanelOpen(false);
        setIsQuoteHistoryPanelClosing(false);
        quoteHistoryPanelCloseTimeoutRef.current = null;
      }, 360);
      return true;
    });
  }, []);

  // Manual "Save Version" — same convention as Specs' own (name it, it appends to history immediately).
  const [isQuoteGridSaveVersionModalOpen, setIsQuoteGridSaveVersionModalOpen] = useState(false);
  const [quoteGridSaveVersionModalOrigin, setQuoteGridSaveVersionModalOrigin] = useState<GlassModalOrigin>(null);
  const quoteGridSaveVersionModalPanelRef = useRef<HTMLDivElement | null>(null);
  const quoteGridSaveVersionModalOriginElRef = useRef<HTMLElement | null>(null);
  const shouldRenderQuoteGridSaveVersionModal = useGlassModalPopOrigin(
    isQuoteGridSaveVersionModalOpen,
    quoteGridSaveVersionModalOrigin,
    quoteGridSaveVersionModalPanelRef,
    undefined,
    quoteGridSaveVersionModalOriginElRef,
  );
  const [quoteGridSaveVersionNameDraft, setQuoteGridSaveVersionNameDraft] = useState("");
  const [isSavingQuoteGridVersion, setIsSavingQuoteGridVersion] = useState(false);

  // Delete a single Quote version from the Version History sidebar — "" means no confirmation is
  // pending. The bubble's own hover-revealed delete icon (see quoteGridVersionsSorted.map below)
  // captures its click point into quoteVersionDeleteOrigin before opening this, same
  // pop-from-click-point convention as every other glass modal in this file.
  const [quoteVersionPendingDeleteId, setQuoteVersionPendingDeleteId] = useState("");
  const [quoteVersionDeleteOrigin, setQuoteVersionDeleteOrigin] = useState<GlassModalOrigin>(null);
  const quoteVersionDeleteModalPanelRef = useRef<HTMLDivElement | null>(null);
  const quoteVersionDeleteModalOriginElRef = useRef<HTMLElement | null>(null);
  const shouldRenderQuoteVersionDeleteModal = useGlassModalPopOrigin(
    Boolean(quoteVersionPendingDeleteId),
    quoteVersionDeleteOrigin,
    quoteVersionDeleteModalPanelRef,
    undefined,
    quoteVersionDeleteModalOriginElRef,
  );
  // Shared by this modal and its Specs twin below — see quoteVersionDeleteModalOpenedAtRef's own
  // comment for why a dismiss this soon after opening is ignored rather than acted on.
  const BACKDROP_DISMISS_GRACE_MS = 400;
  // Stamped the instant this modal opens (both the desktop hover-icon click and the mobile
  // long-press path funnel into the same setQuoteVersionPendingDeleteId(v.id), so one effect here
  // covers both) — read by the backdrop's own onClick below to ignore a dismiss that lands within
  // BACKDROP_DISMISS_GRACE_MS of opening. On mobile specifically, the long-press that OPENS this
  // modal fires while the finger is still down; the backdrop (a full-screen element) mounts right
  // under wherever that finger already is, and some mobile browsers synthesize their end-of-touch
  // click against whatever's CURRENTLY under the finger rather than the original long-pressed row
  // — meaning useLongPress's own preventDefault() on the row's touchend doesn't reliably suppress
  // it, since by then the click is about to land on a different element entirely. Without this, the
  // same lift-finger that completes the long-press immediately re-closes the modal it just opened,
  // so fast that there's no time left for the panel to even finish mounting — reading as "just
  // disappears" rather than a genuine tap-outside dismiss, which only the backdrop (not Cancel/
  // Delete, both deliberate second taps a user wouldn't make within this short a window) needs this
  // guard on.
  const quoteVersionDeleteModalOpenedAtRef = useRef(0);
  useEffect(() => {
    if (quoteVersionPendingDeleteId) quoteVersionDeleteModalOpenedAtRef.current = Date.now();
  }, [quoteVersionPendingDeleteId]);
  const [isDeletingQuoteVersion, setIsDeletingQuoteVersion] = useState(false);
  // Drives the delete icon's slide/bounce via a literal inline `transform` string toggled by real
  // hover state, rather than Tailwind's group-hover translate utilities — those compose `transform`
  // out of an unregistered `--tw-translate-x` custom property, which browsers can't smoothly
  // interpolate (it jumps discretely partway through the transition instead of animating), which is
  // exactly the "doesn't animate, flashes then fades" bug this replaced.
  const [hoveredQuoteVersionId, setHoveredQuoteVersionId] = useState("");
  const deleteQuoteVersionById = async (versionId: string) => {
    if (!project || !versionId || isDeletingQuoteVersion) return;
    // A version that's been sent to the client (accepted or still pending) is never deletable, even
    // from here, so it can't be silently lost by whatever set quoteVersionPendingDeleteId — a client
    // could be looking at it right now, or it's a permanent acceptance record (see acceptedAtIso's
    // own comment in lib/specs-grid-types.ts). The disabled/hidden delete icon already blocks this
    // in the normal UI path; this is the same guarantee for the confirm modal itself.
    const target = quoteGridVersions.find((v) => v.id === versionId);
    if (!target || target.acceptedAtIso || target.sentToClient) return;
    const index = quoteGridVersions.indexOf(target);
    setIsDeletingQuoteVersion(true);
    try {
      const ok = await deleteGridVersion(project, "quoteGridVersions", versionId);
      if (!ok) return;
      // Deleting the version currently open in the editor falls back to the live grid — there's
      // nothing left to display for it.
      if (activeQuoteGridVersionId === versionId) returnToLiveQuoteGrid();
      setQuoteVersionPendingDeleteId("");
      // Actually dropping the row from quoteGridVersions is deferred past the confirm modal's own
      // shrink-back-into-this-row close animation (see DEFAULT_GLASS_MODAL_ORIGIN_CLOSE_HOLD_MS's
      // own comment) — removing it in the same tick as the line above pulls the row (the close
      // animation's own landing target) out from under the still-playing shrink.
      window.setTimeout(() => {
        setQuoteGridVersions((prev) => prev.filter((v) => v.id !== versionId));
        // Undo (offered as the row goes, so it can't be put back before then): its document again, the same id and grid.
        offerUndo(`${target.name || "Version"} deleted`, async () => {
          if (!(await restoreGridVersion(project, "quoteGridVersions", target))) return;
          setQuoteGridVersions((prev) => putBackAt(prev, [{ index, item: target }], (v) => v.id));
        });
      }, DEFAULT_GLASS_MODAL_ORIGIN_CLOSE_HOLD_MS);
    } finally {
      setIsDeletingQuoteVersion(false);
    }
  };

  // Which version is currently being viewed/edited — "" means the live quote. Unlike Specs' history
  // (which only ever offers "restore this over the live grid"), Quote history stays independently
  // editable: opening a version just points this SAME <SpecsGridEditor> at that version's own grid,
  // and edits made while it's open save back into that version's own record, never the live grid.
  const [activeQuoteGridVersionId, setActiveQuoteGridVersionId] = useState("");
  // Local, immediately-responsive edits made while a historical version is open — mirrors what
  // `quoteGrid` state already does for the live grid (the version's own persisted record, read via
