  const [activeQuoteSnapshotId, setActiveQuoteSnapshotId] = useState("");
  const [isQuoteOutdated, setIsQuoteOutdated] = useState(false);
  const [quoteSnapshotHtmlCache, setQuoteSnapshotHtmlCache] = useState<Record<string, string[]>>({});
  const [quoteSnapshotLoadErrors, setQuoteSnapshotLoadErrors] = useState<Record<string, string>>({});
  const [pendingDeleteQuoteSnapshotId, setPendingDeleteQuoteSnapshotId] = useState("");
  const [isDeletingQuoteSnapshot, setIsDeletingQuoteSnapshot] = useState(false);
